  if (!ctx.can_use_app) throw new HttpError(403, 'plan_expired', 'Seu acesso está suspenso ou o período de teste terminou.');
  if (requireAccount) {
    if (!ctx.account) throw new HttpError(404, 'no_account', 'Nenhum número do WhatsApp conectado.');
    if (!ctx.token) throw new HttpError(409, 'no_token', 'Conexão sem token válido. Reconecte o número.');
  }
  return ctx;
}

// ---------------------------------------------------------------- Graph API
/**
 * Chamada à Graph API. O token vai no header (não na URL), então `request` pode ser
 * devolvido ao front com segurança para o painel JSON.
 */
async function graph(method, path, { token, body, qs } = {}) {
  const url = GRAPH + path;
  const r = await http({
    method,
    url,
    qs,
    body,
    headers: token ? { Authorization: `Bearer ${token}` } : {},
  });
  const request = { method, url: url + (qs ? '?' + new URLSearchParams(qs).toString() : '') };
  if (body !== undefined) request.body = body;
  return { ok: r.status >= 200 && r.status < 300, http_status: r.status, request, response: r.body };
}

function metaError(resp) {
  const e = resp && resp.error;
  if (!e) return null;
  return {
    message: e.error_user_msg || e.message,
    code: e.code,
    subcode: e.error_subcode,
    type: e.type,
    fbtrace_id: e.fbtrace_id,
    details: e.error_data && e.error_data.details,
  };
}

/** Oculta segredos por completo (PIN de 6 dígitos, tokens, client_secret, code). */
function maskSecrets(obj) {
  const SECRET_KEYS = ['access_token', 'client_secret', 'input_token', 'pin'];
  const walk = (v) => {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === 'object') {
      const o = {};
      for (const [k, val] of Object.entries(v)) o[k] = SECRET_KEYS.includes(k) ? '***' : walk(val);
      return o;
    }
    if (typeof v === 'string') {
      return v.replace(/(client_secret|code|access_token|input_token)=([^&\s]+)/g, (_, k) => `${k}=***`);
    }
    return v;
  };
  return walk(obj);
}

function step(name, g) {
  return {
    name,
    ok: g.ok,
    http_status: g.http_status,
    request: maskSecrets(g.request),
    response: maskSecrets(g.response),
  };
}

function onlyDigits(v) {
  return String(v || '').replace(/\D/g, '');
}

// ---------------------------------------------------------------- Número de telefone
const PHONE_FIELDS =
  'display_phone_number,verified_name,quality_rating,code_verification_status,name_status,status,is_on_biz_app,platform_type';

/**
 * Limite diário de conversas do número (lacuna 2). Chamada separada e best-effort: o campo é novo
 * (substitui messaging_limit_tier) e, se a versão da Graph não o conhecer, não pode derrubar o resto.
 */
async function fetchMessagingLimit(phoneId, token) {
  const g = await graph('GET', `/${phoneId}`, { token, qs: { fields: 'whatsapp_business_manager_messaging_limit' } });
  const v = g.ok && g.response ? g.response.whatsapp_business_manager_messaging_limit : null;
  return { step: step('messaging_limit', g), limit: v == null ? null : String(v) };
}

/** O app da Monuv aparece na resposta de GET /{waba_id}/subscribed_apps? */
function appIsSubscribed(g) {
  return !!(g.ok && g.response && (g.response.data || []).some(
    (a) => String((a.whatsapp_business_api_data || {}).id) === String(ENV.APP_ID),
  ));
}

/** Converte a resposta de GET /{phone_number_id} nas colunas de wa_accounts. */
function phoneColumns(p) {
  return {
    display_phone_number: p.display_phone_number || null,
    verified_name: p.verified_name || null,
    quality_rating: p.quality_rating || null,
    name_status: p.name_status || null,
    code_verification_status: p.code_verification_status || null,
    phone_status: p.status || null,
    is_on_biz_app: p.is_on_biz_app === true,
    platform_type: p.platform_type || null,
  };
}

// ---------------------------------------------------------------- Envio de template
/** Monta o objeto `template` da Cloud API a partir dos parâmetros enviados pelo front. */
function buildTemplate(name, language, params = {}) {
  const named = params.parameter_format === 'NAMED';
  const textParam = (p) =>
    named ? { type: 'text', parameter_name: p.key, text: String(p.value ?? '') } : { type: 'text', text: String(p.value ?? '') };
  const components = [];

  if (params.header_media && params.header_media.link) {
    const t = params.header_media.type;
    const media = { link: params.header_media.link };
    if (t === 'document' && params.header_media.filename) media.filename = params.header_media.filename;
    components.push({ type: 'header', parameters: [{ type: t, [t]: media }] });
  } else if (Array.isArray(params.header) && params.header.length) {
    components.push({ type: 'header', parameters: params.header.map(textParam) });
  }
  if (Array.isArray(params.body) && params.body.length) {
    components.push({ type: 'body', parameters: params.body.map(textParam) });
  }
  for (const b of params.buttons || []) {
    components.push({
      type: 'button',
      sub_type: 'url',
      index: String(b.index),
      parameters: [{ type: 'text', text: String(b.value ?? '') }],
    });
  }
  const tpl = { name, language: { code: language } };
  if (components.length) tpl.components = components;
  return tpl;
}

/**
 * Envia um template: reserva a cota e grava a mensagem ANTES de chamar a Meta
 * (atômico no banco), envia, e registra a resposta.
 * Retorna { limited } quando o limite diário foi atingido (nada é enviado).
 */
async function sendTemplateMessage({ userId, account, token, to, templateName, language, params, bodyPreview, campaignId }) {
  const payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'template',
    template: buildTemplate(templateName, language, params || {}),
  };

  const reserved = await rpc('reserve_outbound_message', {
    p_user_id: userId,
    p_message: {
      wa_account_id: account.id,
      campaign_id: campaignId || null,
      to_number: to,
      from_number: account.display_phone_number,
      template_name: templateName,
      template_language: language,
      body_preview: typeof bodyPreview === 'string' ? bodyPreview : null,
      request_payload: payload,
    },
  });
  if (!reserved || !reserved.ok) {
    return { limited: reserved && reserved.error === 'daily_limit', reserveError: reserved && reserved.error, dailyLimit: reserved && reserved.daily_send_limit };
  }

  const g = await graph('POST', `/${account.phone_number_id}/messages`, { token, body: payload });
  const sent = g.ok && g.response && g.response.messages && g.response.messages[0];
  const error = sent ? null : metaError(g.response);

  await sb('PATCH', `/rest/v1/messages?id=eq.${reserved.id}`, {
    response_payload: g.response,
    http_status: g.http_status,
    wa_message_id: sent ? sent.id : null,
    status: sent ? 'accepted' : 'failed',
    error,
  }, MINIMAL);
  if (sent) await rpc('attach_message_events', { p_message_id: reserved.id });

  return { sent: !!sent, graph: g, error, messageId: reserved.id, waMessageId: sent ? sent.id : null };
}
// ============================================================================

// action "es.exchange" — finaliza o Embedded Signup (v5, coexistência ligada por padrão)
// body: { code, waba_id?, phone_number_id?, business_id?, event?, is_on_biz_app? }
//
// Coexistência (número que continua no app WhatsApp Business): NÃO registra o número
// (já está registrado) e, se MONUV_COEX_SYNC=true, pede contatos + histórico do app
// (a Meta só aceita esse pedido uma vez, até 24 h após o onboarding).
//
// Ordem importa (auditoria run-1): toda checagem de posse acontece ANTES de qualquer
// efeito colateral na Meta (subscribed_apps, register) ou no banco.
const { user, body } = $input.first().json; // vindo do Roteador (já autenticado)
const steps = [];

/** WABAs que o token trocado realmente pode gerenciar (falha fechado). */
async function grantedWabas(token) {
  const dbg = await graph('GET', '/debug_token', { qs: { input_token: token }, token: `${ENV.APP_ID}|${ENV.APP_SECRET}` });
  steps.push(step('debug_token', dbg));
  const scopes = (dbg.ok && dbg.response.data && dbg.response.data.granular_scopes) || [];
  const mgmt = scopes.find((s) => s.scope === 'whatsapp_business_management');
  const ids = ((mgmt && mgmt.target_ids) || []).map(String);
  if (!ids.length) throw new HttpError(403, 'waba_not_granted', 'O token não concede acesso a nenhuma conta do WhatsApp Business.');
  return ids;
}

/** Números da WABA visíveis para o token trocado. */
async function grantedPhones(wabaId, token) {
  const phones = [];
  let after = null;
  for (let page = 0; page < 10; page++) {
    const qs = { fields: 'id', limit: '100' };
    if (after) qs.after = after;
    const list = await graph('GET', `/${wabaId}/phone_numbers`, { token, qs });
    steps.push(step('list_phone_numbers', list));
    if (!list.ok) break;
    phones.push(...(list.response.data || []).map((p) => String(p.id)));
    after = list.response.paging && list.response.paging.next && list.response.paging.cursors ? list.response.paging.cursors.after : null;
    if (!after) break;
  }
  return phones;
}

async function assertPhoneFree(phoneId, userId) {
  const existing = await sb('GET', `/rest/v1/wa_accounts?phone_number_id=eq.${encodeURIComponent(phoneId)}&select=user_id`);
  if (existing.length && existing[0].user_id !== userId) {
    throw new HttpError(409, 'phone_in_use', 'Este número já está conectado a outra conta Monuv.');
  }
}

/** Registra o número na Cloud API com PIN aleatório. Retorna { registered, pin }. */
async function registerPhone(phoneId, token) {
  const pin = String(require('crypto').randomInt(0, 1000000)).padStart(6, '0');
  const reg = await graph('POST', `/${phoneId}/register`, { token, body: { messaging_product: 'whatsapp', pin } });
  steps.push(step('register_phone', reg));
  const err = metaError(reg.response);
  const already = !!(err && /already registered/i.test(err.message || ''));
  return { registered: reg.ok || already, pin: reg.ok ? pin : null };
}

/** Coexistência: a Graph API é a fonte da verdade; a dica do navegador só vale se a Graph falhar. */
function isCoexistence(phoneDetails) {
  if (phoneDetails.ok) return phoneDetails.response.is_on_biz_app === true;
  return body.is_on_biz_app === true || body.event === 'FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING';
}

/** Pede à Meta os contatos e depois o histórico do app (nessa ordem, como a Meta recomenda). */
async function requestCoexSync(phoneId, token) {
  let any = false;
  for (const syncType of ['smb_app_state_sync', 'history']) {
    const r = await graph('POST', `/${phoneId}/smb_app_data`, { token, body: { messaging_product: 'whatsapp', sync_type: syncType } });
    steps.push(step(`sync_${syncType}`, r));
    any = any || r.ok;
  }
  return any;
}

try {
  await userContext(user.id, null, { requireAccount: false });

  if (!body.code) throw new HttpError(400, 'bad_request', 'Parâmetro "code" ausente.');
  if (!ENV.APP_ID || !ENV.APP_SECRET) throw new HttpError(500, 'config', 'MONUV_META_APP_ID / MONUV_META_APP_SECRET não configurados.');
  secretKey(); // sem chave de cifragem não há onde guardar o token: falha antes de qualquer efeito na Meta

  // 1) code → token
  const ex = await graph('GET', '/oauth/access_token', {
    qs: { client_id: ENV.APP_ID, client_secret: ENV.APP_SECRET, code: body.code },
  });
  steps.push(step('exchange_code', ex));
  if (!ex.ok || !ex.response.access_token) {
    throw new HttpError(502, 'exchange_failed', (metaError(ex.response) || {}).message || 'Falha ao trocar o code pelo token.');
  }
  const token = ex.response.access_token;

  // 2) WABA precisa estar entre as concedidas ao token
  const wabas = await grantedWabas(token);
  const wabaId = body.waba_id ? String(body.waba_id) : wabas[wabas.length - 1];
  if (!wabas.includes(wabaId)) throw new HttpError(403, 'waba_not_granted', 'A WABA informada não foi autorizada para este aplicativo.');

  // 3) número precisa pertencer a essa WABA, visto pelo próprio token
  const phones = await grantedPhones(wabaId, token);
  const phoneId = body.phone_number_id ? String(body.phone_number_id) : phones[0];
  if (!phoneId || !phones.includes(phoneId)) {
    throw new HttpError(403, 'phone_not_granted', 'O número informado não pertence à conta do WhatsApp autorizada.');
  }

  // 4) número livre (ou já deste usuário) — ainda sem nenhum efeito colateral
  await assertPhoneFree(phoneId, user.id);

  // 5) efeitos na Meta: assina webhooks e CONFERE que o app da Monuv aparece na lista.
  //    Sem essa inscrição o cliente conecta mas nunca recebe um evento de webhook.
  const sub = await graph('POST', `/${wabaId}/subscribed_apps`, { token });
  steps.push(step('subscribe_app', sub));
  const subCheck = await graph('GET', `/${wabaId}/subscribed_apps`, { token });
  steps.push(step('subscribed_apps', subCheck));
  const subscribed = appIsSubscribed(subCheck);

  // 6) detalhes (dizem se o número está em coexistência) e registro só fora da coexistência
  const ph = await graph('GET', `/${phoneId}`, { token, qs: { fields: PHONE_FIELDS } });
  steps.push(step('phone_details', ph));
  const wb = await graph('GET', `/${wabaId}`, { token, qs: { fields: 'name' } });
  steps.push(step('waba_details', wb));
  const limit = await fetchMessagingLimit(phoneId, token);
  steps.push(limit.step);
  const coexistence = isCoexistence(ph);
  const { registered, pin } = coexistence ? { registered: true, pin: null } : await registerPhone(phoneId, token);

  // 7) vínculo atômico que nunca troca o dono de um número
  const ready = registered && subscribed;
  const claim = await rpc('claim_wa_account', {
    p_user_id: user.id,
    p_row: {
      business_id: body.business_id ? String(body.business_id) : null,
      waba_id: wabaId,
      waba_name: wb.ok ? wb.response.name : null,
      phone_number_id: phoneId,
      ...(ph.ok ? phoneColumns(ph.response) : {}),
      is_on_biz_app: coexistence,
      messaging_limit: limit.limit,
      status: ready ? 'connected' : 'pending',
      webhook_subscribed: subscribed,
      last_error: ready ? null : { steps: steps.filter((s) => !s.ok).map((s) => s.name) },
    },
  });
  if (!claim || !claim.ok) throw new HttpError(409, 'phone_in_use', 'Este número já está conectado a outra conta Monuv.');
  const account = claim.account;

  await storeSecret(account.id, 'token', token);
  if (pin) await storeSecret(account.id, 'pin', pin);
  steps.push({ name: 'save_account', ok: true, response: { wa_account_id: account.id, status: account.status } });

  // 8) coexistência: sincronização única, só depois do vínculo garantido
  let saved = account;
  if (coexistence && ENV.COEX_SYNC && await requestCoexSync(phoneId, token)) {
    const rows = await sb('PATCH', `/rest/v1/wa_accounts?id=eq.${account.id}`, { coex_sync_requested_at: new Date().toISOString() });
    saved = rows[0] || account;
  }

  return respond(200, { ok: true, data: { account: saved, coexistence }, account: saved, coexistence, steps });
} catch (e) {
  return handleError(e, { steps });
}

// ============================================================================
// monuv lib — gerado por n8n/build.mjs a partir de n8n/src/_lib.js.
// NÃO edite no n8n: edite no repositório e reimporte o workflow.
// Requer no n8n: N8N_BLOCK_ENV_ACCESS_IN_NODE=false
// ============================================================================
const ENV = {
  SUPABASE_URL: String($env.MONUV_SUPABASE_URL || '').replace(/\/+$/, ''),
  SERVICE_KEY: $env.MONUV_SUPABASE_SERVICE_ROLE_KEY,
  APP_ID: $env.MONUV_META_APP_ID,
  APP_SECRET: $env.MONUV_META_APP_SECRET,
  VERIFY_TOKEN: $env.MONUV_META_VERIFY_TOKEN,
  GRAPH_VERSION: $env.MONUV_GRAPH_VERSION || 'v24.0',
  // Coexistência: pedir à Meta contatos + histórico (até 180 dias) do app WhatsApp Business no onboarding
  COEX_SYNC: String($env.MONUV_COEX_SYNC || '').toLowerCase() === 'true',
  // Chave AES-256-GCM (32 bytes em base64) que cifra token e PIN dos clientes antes de irem ao Supabase
  TOKEN_KEY: $env.MONUV_TOKEN_ENCRYPTION_KEY,
};
const GRAPH = `https://graph.facebook.com/${ENV.GRAPH_VERSION}`;
const helpers = this.helpers;
const EXECUTION_ID = (typeof $execution !== 'undefined' && $execution && $execution.id) || null;

/** Erro com status HTTP. Status < 500 = erro do cliente (mensagem vai ao navegador). */
class HttpError extends Error {
  constructor(status, code, message, extra = {}, detail = null) {
    super(message);
    this.status = status;
    this.code = code;
    this.extra = extra;
    this.detail = detail;
  }
}

function respond(status, body) {
  return [{ json: { status, body } }];
}

/** Registra detalhes internos no Supabase (app_errors) — nunca no corpo da resposta. */
async function logInternalError(e) {
  try {
    await sb('POST', '/rest/v1/app_errors', {
      execution_id: EXECUTION_ID,
      code: (e && e.code) || 'internal',
      message: String((e && e.message) || e).slice(0, 2000),
      detail: (e && e.detail) || null,
    }, { Prefer: 'return=minimal' });
  } catch (_) { /* registro é best-effort */ }
}

async function handleError(e, extra = {}) {
  if (e instanceof HttpError && e.status < 500) {
    return respond(e.status, { ok: false, error: { code: e.code, message: e.message }, ...extra, ...e.extra });
  }
  await logInternalError(e);
  return respond(500, {
    ok: false,
    error: { code: 'internal', message: 'Erro interno. Informe a referência ao suporte.', ref: EXECUTION_ID },
    ...extra,
  });
}

async function http(opts) {
  const res = await helpers.httpRequest({
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true,
    timeout: 30000,
    ...opts,
  });
  let body = res.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (_) { /* texto */ }
  }
  return { status: res.statusCode, body };
}

// ---------------------------------------------------------------- Supabase
async function sb(method, path, body, headers = {}) {
  if (!ENV.SUPABASE_URL || !ENV.SERVICE_KEY) {
    throw new HttpError(500, 'config', 'MONUV_SUPABASE_URL / MONUV_SUPABASE_SERVICE_ROLE_KEY não configurados no n8n.');
  }
  const r = await http({
    method,
    url: ENV.SUPABASE_URL + path,
    headers: {
      apikey: ENV.SERVICE_KEY,
      Authorization: `Bearer ${ENV.SERVICE_KEY}`,
      'Content-Type': 'application/json',
      Prefer: 'return=representation',
      ...headers,
    },
    body,
  });
  if (r.status >= 300) {
    throw new HttpError(502, 'supabase_error', `Supabase ${method} ${path.split('?')[0]} → ${r.status}`, {}, r.body);
  }
  return r.body;
}

const MINIMAL = { Prefer: 'return=minimal' };

async function rpc(fn, args) {
  return sb('POST', `/rest/v1/rpc/${fn}`, args);
}

/** Valida o JWT do usuário (Authorization: Bearer <access_token do Supabase>). */
async function authUser(req) {
  const h = req.headers || {};
  const authz = h.authorization || h.Authorization || '';
  const jwt = String(authz).replace(/^Bearer\s+/i, '').trim();
  if (!jwt) throw new HttpError(401, 'unauthorized', 'Token de acesso ausente.');
  const r = await http({
    method: 'GET',
    url: `${ENV.SUPABASE_URL}/auth/v1/user`,
    headers: { apikey: ENV.SERVICE_KEY, Authorization: `Bearer ${jwt}` },
  });
  if (r.status !== 200 || !r.body || !r.body.id) throw new HttpError(401, 'unauthorized', 'Sessão inválida ou expirada.');
  return r.body;
}

// ---------------------------------------------------------------- Segredos dos clientes (lacuna 4)
// Token e PIN são cifrados AQUI, com AES-256-GCM, antes de irem ao Supabase (que ainda os guarda no Vault).
// Quem tiver só um dump do banco ou só a service_role key não consegue usar o token: falta a chave do n8n.
// Formato: "enc:v1:" + base64(iv[12] | tag[16] | texto cifrado). AAD = conta + tipo, então um segredo
// copiado para outra conta não decifra.
const SECRET_PREFIX = 'enc:v1:';

function secretKey() {
  const raw = ENV.TOKEN_KEY ? Buffer.from(String(ENV.TOKEN_KEY), 'base64') : null;
  if (!raw || raw.length !== 32) {
    throw new HttpError(500, 'config', 'MONUV_TOKEN_ENCRYPTION_KEY ausente ou inválida (gere com: openssl rand -base64 32).');
  }
  return raw;
}

function sealSecret(plain, accountId, kind) {
  const c = require('crypto');
  const iv = c.randomBytes(12);
  const cipher = c.createCipheriv('aes-256-gcm', secretKey(), iv);
  cipher.setAAD(Buffer.from(`wa:${accountId}:${kind}`, 'utf8'));
  const ct = Buffer.concat([cipher.update(String(plain), 'utf8'), cipher.final()]);
  return SECRET_PREFIX + Buffer.concat([iv, cipher.getAuthTag(), ct]).toString('base64');
}

function openSecret(stored, accountId, kind) {
  if (!stored) return null;
  // Legado: segredo gravado antes da cifragem no n8n. Continua funcionando até a próxima reconexão.
  if (!String(stored).startsWith(SECRET_PREFIX)) return String(stored);
  const c = require('crypto');
  const buf = Buffer.from(String(stored).slice(SECRET_PREFIX.length), 'base64');
  try {
    const decipher = c.createDecipheriv('aes-256-gcm', secretKey(), buf.subarray(0, 12));
    decipher.setAAD(Buffer.from(`wa:${accountId}:${kind}`, 'utf8'));
    decipher.setAuthTag(buf.subarray(12, 28));
    return Buffer.concat([decipher.update(buf.subarray(28)), decipher.final()]).toString('utf8');
  } catch (e) {
    if (e instanceof HttpError) throw e;
    throw new HttpError(500, 'secret_decrypt', 'Não foi possível decifrar o token da conexão (chave trocada?).');
  }
}

/** Grava token/PIN cifrado. Nunca grava texto puro: sem chave, falha antes. */
async function storeSecret(accountId, kind, value) {
  return rpc('wa_store_secret', { p_wa_account_id: accountId, p_kind: kind, p_value: sealSecret(value, accountId, kind) });
}

/** Contexto do usuário (profile + conta WhatsApp + token decifrado). Nunca devolva `token` na resposta. */
async function userContext(userId, waAccountId, { requireAccount = true } = {}) {
  const ctx = await rpc('n8n_user_context', { p_user_id: userId, p_wa_account_id: waAccountId || null });
  if (!ctx || !ctx.ok) throw new HttpError(403, 'no_profile', 'Perfil não encontrado.');
  ctx.token = ctx.account && ctx.token ? openSecret(ctx.token, ctx.account.id, 'token') : null;
  if (!ctx.can_use_app) throw new HttpError(403, 'plan_expired', 'Seu acesso está suspenso ou o período de teste terminou.');
  if (requireAccount) {
    if (!ctx.account) throw new HttpError(404, 'no_account', 'Nenhum número do WhatsApp conectado.');
    if (!ctx.token) throw new HttpError(409, 'no_token', 'Conexão sem token válido. Reconecte o número.');
  }
  return ctx;
}

// ---------------------------------------------------------------- Graph API
/**
 * Chamada à Graph API. O token vai no header (não na URL), então `request` pode ser
 * devolvido ao front com segurança para o painel JSON.
 */
async function graph(method, path, { token, body, qs } = {}) {
